=<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Zoho Community Subscriptions</title>
</head>
<body>

<div class="app">
  <header class="page-header">
    <div class="header-copy">
      <div class="eyebrow">ZOHO COMMUNITY</div>
      <h1>Community subscriptions</h1>
      <p>Choose which categories and activity types you want to monitor.</p>
    </div>
  </header>

  <div class="toolbar">
    <div class="search">
      <span class="search-icon">⌕</span>
      <input id="search" type="search" placeholder="Search categories..." autocomplete="off">
      <button id="clearSearch" class="clear-search" type="button" aria-label="Clear search" hidden>×</button>
    </div>
    <div class="summary">
      <div class="summary-item"><strong id="categoryCount">0</strong><span>categories</span></div>
      <div class="summary-divider"></div>
      <div class="summary-item"><strong id="activeCount">0</strong><span>active</span></div>
      <div id="changeBadge" class="change-badge" hidden>
        <span class="change-dot"></span><strong id="totalChanges">0</strong><span>changes</span>
      </div>
    </div>
  </div>

  <div class="card">
    <div class="card-header">
      <div>Category</div>
      <div class="column-title">Announcements</div>
      <!-- <div class="column-title">Problems</div> -->
    </div>
    <div id="categories"></div>
  </div>

  <div class="footer" id="footer">
    <div class="footer-status">
      <div id="changes" class="changes">No unsaved changes</div>
    </div>
    <div class="footer-actions">
      <button id="dropButton" class="drop-button" type="button" disabled>Drop changes</button>
      <button id="saveButton" class="save-button" type="button" disabled>
        <span class="button-label">Save changes</span>
      </button>
    </div>
  </div>
</div>

<div id="loadingOverlay" class="loading-overlay" hidden>
  <div class="loading-card">
    <div class="big-loader"></div>
    <div class="loading-title">Saving subscriptions</div>
    <div class="loading-text">Please wait while your subscription settings are saved.</div>
  </div>
</div>

<div id="toast" class="toast" aria-live="polite"></div>

<script>
const portalId = "{{ $('Get Zoho Community portal ID for admin panel').first().json.data.match(/portalId[^a-zA-Z0-9]+([a-zA-Z0-9]+)/)?.[1] }}";
const communityCategories = {{ JSON.stringify($('Fetch Zoho Community categories').item.json.data) }};
const existingSubscriptions = {{ JSON.stringify($json.data ?? []) }};
const SAVE_URL = "/webhook/oz-upsertZohoCommunitySubscriptionStatus";

let categories = [];
let original = new Map();
let current = new Map();
const expanded = new Set();

const $ = id => document.getElementById(id);

const categoriesEl = $("categories");
const searchEl = $("search");
const clearSearchBtn = $("clearSearch");
const saveBtn = $("saveButton");
const dropBtn = $("dropButton");
const changesEl = $("changes");
const categoryCountEl = $("categoryCount");
const activeCountEl = $("activeCount");
const totalChangesEl = $("totalChanges");
const changeBadgeEl = $("changeBadge");
const footerEl = $("footer");
const loadingOverlay = $("loadingOverlay");
const toastEl = $("toast");

function categoryPhoto(category) {
  if (!category.photoUrl) return "";
  return `${category.photoUrl}${category.photoUrl.includes("?") ? "&" : "?"}portalId=${encodeURIComponent(portalId)}`;
}

function esc(value) {
  return String(value ?? "")
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;")
    .replaceAll("'","&#039;");
}

function state(value = {}) {
  return {
    listenForAnnouncements: value.listenForAnnouncements === true,
    listenForProblems: false
  };
}

function cloneState(value) {
  return {
    listenForAnnouncements: !!value.listenForAnnouncements,
    listenForProblems: false
  };
}

function flatten(items, level = 0, parentId = null, output = [], parentPath = "") {
  for (const category of [...(items || [])].sort((a, b) => (Number(b?.postCount) || 0) - (Number(a?.postCount) || 0))) {
    if (!category) continue;

    const categoryPath = parentPath
      ? `${parentPath}/${category.name || category.permalink}`
      : (category.name || category.permalink);

    const item = {
      ...category,
      _id: String(category.id),
      _level: level,
      _parentId: parentId,
      _categoryPath: categoryPath,
      _isParent: Array.isArray(category.child) && category.child.length > 0
    };

    output.push(item);

    if (item._isParent) {
      flatten(category.child, level + 1, item._id, output, categoryPath);
    }
  }

  return output;
}

function getDescendants(id) {
  const index = categories.findIndex(c => c._id === String(id));
  if (index === -1) return [];

  const parent = categories[index];
  const result = [];

  for (let i = index + 1; i < categories.length; i++) {
    const category = categories[i];

    if (category._level <= parent._level) break;

    result.push(category);
  }

  return result;
}

function getBranch(id) {
  const category = categories.find(c => c._id === String(id));
  return category ? [category, ...getDescendants(id)] : [];
}

function getDirectChildren(id) {
  return categories.filter(c => c._parentId === String(id));
}

function isParentListening(id) {
  const category = categories.find(c => c._id === String(id));
  return !!(
    category &&
    category._isParent &&
    (current.get(category._id) || state()).listenForAnnouncements
  );
}

function getTotalChanges() {
  let count = 0;

  for (const category of categories) {
    const a = current.get(category._id) || state();
    const b = original.get(category._id) || state();

    if (a.listenForAnnouncements !== b.listenForAnnouncements) count++;
    if (a.listenForProblems !== b.listenForProblems) count++;
  }

  return count;
}

function isChanged(id, type) {
  const a = current.get(String(id)) || state();
  const b = original.get(String(id)) || state();

  return a[type] !== b[type];
}



categories = flatten(
  Array.isArray(communityCategories)
    ? communityCategories
    : (communityCategories?.data || communityCategories?.categories || [])
);


for (const subscription of existingSubscriptions || []) {
  const categoryId = String(subscription.categoryId);

  original.set(categoryId, cloneState(subscription));
  current.set(categoryId, cloneState(subscription));
}


for (const category of categories) {
  if (!current.has(category._id))
    current.set(category._id, state());

  if (!original.has(category._id))
    original.set(category._id, state());
}


render();


function render() {
  const query = searchEl.value.trim().toLowerCase();

  clearSearchBtn.hidden = !query;

  let visible;

  if (query) {
    const matches = new Set();

    for (const category of categories) {
      const text = [
        category.name,
        category.description,
        category.permalink
      ].join(" ").toLowerCase();

      if (text.includes(query))
        matches.add(category._id);
    }

    for (const category of categories) {
      if (!matches.has(category._id)) continue;

      let parent = category._parentId;

      while (parent) {
        matches.add(parent);

        const parentCategory =
          categories.find(c => c._id === String(parent));

        if (!parentCategory) break;

        parent = parentCategory._parentId;
      }
    }

    visible = categories.filter(c => matches.has(c._id));

  } else {

    visible = categories.filter(category => {
      let parent = category._parentId;

      while (parent) {
        if (!expanded.has(parent))
          return false;

        const parentCategory =
          categories.find(c => c._id === String(parent));

        if (!parentCategory) break;

        parent = parentCategory._parentId;
      }

      return true;
    });
  }


  categoriesEl.innerHTML = visible.length
    ? visible.map(renderCategory).join("")
    : `
      <div class="empty">
        <strong>No categories found</strong>
      </div>
    `;

  updateUI();
}


function renderCategory(category) {
  const id = category._id;
  const currentState = current.get(id) || state();

  const ownAnnouncementState = !!(current.get(id) || state()).listenForAnnouncements;

  const disabledByParent = !!(
    category._parentId &&
    isParentListening(category._parentId)
  );

  const changed =
    isChanged(id,"listenForAnnouncements");

  const indent = Math.min(category._level * 30,150);
  const children = category._isParent
    ? getDirectChildren(id)
    : [];

  const expandedState = expanded.has(id);

  return `
<div class="category ${category._isParent ? "category-parent":""}"
 data-id="${id}"
 style="--indent:${indent}px">

<div class="category-info" style="padding-left:${indent}px">

<div class="category-name-row">

${
category._isParent
? `
<button class="expand-button"
 data-expand="${id}">
›
</button>
`
:
`<span class="expand-spacer"></span>`
}

<div class="category-title-flex">
${categoryPhoto(category) ? `<img class="category-icon" src="${esc(categoryPhoto(category))}" onerror="this.style.display='none'">` : ""}
<div class="category-name">${esc(category.name || category.permalink)}</div>
${
category._isParent
? `<span class="parent-badge">${children.length} children</span>`
:""
}
</div>

</div>

<div class="category-meta">
${esc(category.permalink)}
${category.postCount ? `<span class="meta-badge">${esc(category.postCount)} posts</span>` : ""}
${category.commentCount ? `<span class="meta-badge">${esc(category.commentCount)} comments</span>` : ""}
</div>

</div>


<div class="toggle-cell">

<label class="switch">

<input
type="checkbox"
data-id="${id}"
data-type="listenForAnnouncements"
data-scope="self"
${ownAnnouncementState ? "checked" : ""}
${disabledByParent ? "disabled" : ""}
>

<span class="slider"></span>

</label>


${changed ? "*" : ""}

</div>


</div>
`;
}



categoriesEl.addEventListener("click",e=>{

const button=e.target.closest("[data-expand]");
if(!button)return;

const id=button.dataset.expand;

if(expanded.has(id)){

for(const c of getBranch(id))
expanded.delete(c._id);

}else{
expanded.add(id);
}

render();

});


categoriesEl.addEventListener("change",e=>{

const input=e.target;

if(!(input instanceof HTMLInputElement))
return;

const id=input.dataset.id;
const type=input.dataset.type;
const scope=input.dataset.scope;

const category =
categories.find(c=>c._id===String(id));

if(!category)return;


const affected = [category];


for(const item of affected){

const next =
cloneState(current.get(item._id)||state());

next[type]=input.checked;

current.set(item._id,next);

}

// When a parent category is enabled, disable all children and turn them off.
if (
category._isParent &&
type === "listenForAnnouncements" &&
input.checked
) {
for (const child of getDescendants(category._id)) {
const next = cloneState(current.get(child._id) || state());
next.listenForAnnouncements = false;
current.set(child._id, next);
}
}

render();

});



searchEl.addEventListener("input",render);


clearSearchBtn.addEventListener("click",()=>{

searchEl.value="";
searchEl.focus();
render();

});



dropBtn.addEventListener("click",()=>{

current=new Map();

for(const c of categories)
current.set(
c._id,
cloneState(original.get(c._id)||state())
);

render();

});



saveBtn.addEventListener("click",save);



async function save(){

const subscriptions =
categories.map(category=>({

id:category.id,
permalink:category.permalink,
categoryName:category._categoryPath,

...(
current.get(category._id)||state()
)

}));


setLoading(true);

try{

await fetch(SAVE_URL,{
method:"POST",
headers:{
"Content-Type":"application/json"
},
body:JSON.stringify({subscriptions})
});


original=new Map();

for(const s of subscriptions)
original.set(String(s.id),cloneState(s));


render();

showToast("Saved successfully","success");


}catch(e){

console.error(e);
showToast(e.message,"error");

}
finally{

setLoading(false);

}

}



function updateUI(){

let active=0;

for(const c of categories){

const s=current.get(c._id)||state();

if(s.listenForAnnouncements)
active++;

}


const changes=getTotalChanges();
const dirty=changes>0;


categoryCountEl.textContent=categories.length;
activeCountEl.textContent=active;
totalChangesEl.textContent=changes;


changeBadgeEl.hidden=!dirty;
saveBtn.disabled=!dirty;
dropBtn.disabled=!dirty;


footerEl.classList.toggle(
"has-changes",
dirty
);


changesEl.textContent=
dirty
? `${changes} settings changed`
: "No unsaved changes";

}



function setLoading(v){

loadingOverlay.hidden=!v;

}



let toastTimer;

function showToast(message,type){

toastEl.textContent=message;
toastEl.className=`toast visible ${type}`;

clearTimeout(toastTimer);

toastTimer=setTimeout(()=>{
toastEl.classList.remove("visible");
},4000);

}


window.addEventListener("beforeunload",e=>{

if(getTotalChanges()){

e.preventDefault();
e.returnValue="";

}

});


setLoading(false);

</script>

<style>
* { box-sizing: border-box; }

html { min-height: 100%; }

body {
  margin: 0;
  font-family: Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  background: #f6f7fb;
  color: #172033;
  -webkit-font-smoothing: antialiased;
}

.app {
  width: min(1180px,calc(100% - 40px));
  margin: 0 auto;
  padding: 42px 0 90px;
}

/* =========================================================
   HEADER
========================================================= */

.page-header { margin-bottom: 28px; }

.eyebrow {
  display: inline-flex;
  align-items: center;
  margin-bottom: 9px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
  color: #635bff;
}

.page-header h1 {
  margin: 0 0 8px;
  font-size: 31px;
  line-height: 1.2;
  letter-spacing: -.7px;
  color: #101828;
}

.page-header p {
  margin: 0;
  color: #667085;
  font-size: 14px;
}

/* =========================================================
   TOOLBAR
========================================================= */

.toolbar {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 15px;
}

.search {
  position: relative;
  flex: 1;
  min-width: 260px;
}

.search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: #98a2b3;
  font-size: 19px;
  pointer-events: none;
}

.search input {
  width: 100%;
  height: 44px;
  padding: 0 42px;
  border: 1px solid #d9dee8;
  border-radius: 10px;
  outline: none;
  background: #fff;
  color: #172033;
  font-size: 14px;
  transition: border-color .15s,box-shadow .15s;
}

.search input::placeholder { color: #98a2b3; }

.search input:focus {
  border-color: #635bff;
  box-shadow: 0 0 0 3px rgba(99,91,255,.10);
}

.clear-search {
  position: absolute;
  right: 9px;
  top: 50%;
  transform: translateY(-50%);
  width: 27px;
  height: 27px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: #f2f4f7;
  color: #667085;
  cursor: pointer;
  font-size: 18px;
  line-height: 27px;
}

.clear-search:hover { background: #e4e7ec; }

/* =========================================================
   SUMMARY
========================================================= */

.summary {
  display: flex;
  align-items: center;
  gap: 13px;
  flex-shrink: 0;
  color: #667085;
  font-size: 12px;
}

.summary-item {
  display: flex;
  align-items: baseline;
  gap: 5px;
  white-space: nowrap;
}

.summary-item strong {
  color: #172033;
  font-size: 14px;
}

.summary-divider {
  width: 1px;
  height: 18px;
  background: #dfe3ea;
}

.change-badge {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 9px;
  border: 1px solid #fedf89;
  border-radius: 999px;
  background: #fffaeb;
  color: #92400e;
}

.change-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #f79009;
}

/* =========================================================
   CARD
========================================================= */

.card {
  overflow: hidden;
  border: 1px solid #e4e7ec;
  border-radius: 15px;
  background: #fff;
  box-shadow: 0 2px 7px rgba(16,24,40,.035);
}

.card-header,.category {
  display: grid;
  grid-template-columns: minmax(0,1fr) 140px 140px;
  gap: 20px;
  align-items: center;
}

.card-header {
  min-height: 48px;
  padding: 0 20px;
  border-bottom: 1px solid #eaecf0;
  background: #fafbfc;
  color: #667085;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .7px;
  text-transform: uppercase;
}

.column-title { text-align: center; }

/* =========================================================
   CATEGORY
========================================================= */

.category {
  min-height: 82px;
  padding: 13px 20px;
  border-bottom: 1px solid #f0f2f5;
  transition: background .15s;
}

.category:last-child { border-bottom: 0; }

.category:hover { background: #fafbff; }

.category-parent { background: #fcfcff; }

.category-parent:hover { background: #f8f8ff; }

.category-info { min-width: 0; }

.category-name-row {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 7px;
}

.expand-button {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: #667085;
  cursor: pointer;
}

.expand-button:hover {
  background: #f2f4f7;
  color: #344054;
}

.expand-chevron {
  display: block;
  font-size: 19px;
  line-height: 1;
  transform: translateX(-1px);
  transition: transform .16s ease;
}

.expand-button.expanded .expand-chevron {
  transform: rotate(90deg) translateX(-1px);
}

.expand-button:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(99,91,255,.16);
}

.expand-spacer {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
}

.category-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #1d2939;
  font-size: 14px;
  font-weight: 600;
}

.category-parent .category-name {
  color: #101828;
  font-weight: 700;
}

.parent-badge {
  flex: 0 0 auto;
  padding: 2px 7px;
  border: 1px solid #e4e7ec;
  border-radius: 999px;
  background: #f9fafb;
  color: #667085;
  font-size: 10px;
  font-weight: 600;
}

.category-description {
  overflow: hidden;
  margin-top: 4px;
  color: #667085;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.category-meta {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 6px;
  overflow: hidden;
  color: #98a2b3;
  font-size: 10px;
}

.category-meta span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.meta-dot { flex: 0 0 auto; }

/* =========================================================
   TOGGLES
========================================================= */

.toggle-cell {
  display: flex;
  align-items: center;
  justify-content: center;
}

.toggle-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 70px;
}

.switch {
  position: relative;
  display: inline-block;
  width: 44px;
  height: 25px;
}

.switch input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.slider {
  position: absolute;
  inset: 0;
  cursor: pointer;
  border-radius: 999px;
  background: #d0d5dd;
  transition: background .18s;
}

.slider::before {
  content: "";
  position: absolute;
  width: 19px;
  height: 19px;
  left: 3px;
  top: 3px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(0,0,0,.22);
  transition: transform .18s;
}

.switch input:checked + .slider { background: #635bff; }

.switch input:checked + .slider::before { transform: translateX(19px); }

.switch input:indeterminate + .slider { background: #a5b4fc; }

.switch input:indeterminate + .slider::before { transform: translateX(9px); }

.switch input:focus-visible + .slider {
  box-shadow: 0 0 0 3px rgba(99,91,255,.20);
}

/* =========================================================
   CHANGE STAR
========================================================= */

.change-star {
  position: absolute;
  right: calc(100% + 6px);
  top: 50%;
  transform: translateY(-50%);
  color: #f79009;
  font-size: 17px;
  font-weight: 800;
  line-height: 1;
  animation: starIn .18s ease-out;
}

@keyframes starIn {
  from { opacity: 0; transform: translateY(-50%) scale(.5); }
  to { opacity: 1; transform: translateY(-50%) scale(1); }
}

/* =========================================================
   EMPTY
========================================================= */

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 260px;
  gap: 5px;
  color: #667085;
}

.empty-icon {
  margin-bottom: 5px;
  color: #98a2b3;
  font-size: 30px;
}

.empty strong {
  color: #344054;
  font-size: 14px;
}

.empty span { font-size: 12px; }

/* =========================================================
   FOOTER
========================================================= */

.footer {
  position: sticky;
  bottom: 14px;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 17px;
  padding: 12px 14px 12px 16px;
  border: 1px solid #e4e7ec;
  border-radius: 13px;
  background: rgba(255,255,255,.96);
  box-shadow: 0 8px 30px rgba(16,24,40,.10);
  backdrop-filter: blur(12px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(18px) scale(.98);
  transition: opacity .22s ease,transform .22s ease,visibility 0s linear .22s;
}

.footer.has-changes {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0) scale(1);
  transition: opacity .22s ease,transform .22s ease;
}

.footer-status {
  display: flex;
  align-items: center;
  min-width: 0;
}

.footer-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.changes {
  color: #667085;
  font-size: 12px;
}

.changes.dirty {
  color: #344054;
  font-weight: 600;
}

.drop-button {
  height: 40px;
  padding: 0 12px;
  border: 1px solid #d0d5dd;
  border-radius: 9px;
  background: #fff;
  color: #667085;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background .15s,border-color .15s,color .15s;
}

.drop-button:hover:not(:disabled) {
  background: #f9fafb;
  border-color: #bfc5d0;
  color: #344054;
}

.drop-button:disabled {
  opacity: .45;
  cursor: not-allowed;
}

.save-button {
  min-width: 135px;
  height: 40px;
  padding: 0 18px;
  border: 0;
  border-radius: 9px;
  background: #635bff;
  color: #fff;
  font-size: 13px;
  font-weight: 650;
  cursor: pointer;
  transition: background .15s,transform .1s,opacity .15s;
}

.save-button:hover:not(:disabled) { background: #554cf0; }

.save-button:active:not(:disabled) { transform: translateY(1px); }

.save-button:disabled {
  opacity: .45;
  cursor: not-allowed;
}

/* =========================================================
   LOADING
========================================================= */

.loading-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(15,23,42,.38);
  backdrop-filter: blur(4px);
}

.loading-overlay[hidden] { display: none !important; }

.loading-card {
  width: min(360px,calc(100% - 40px));
  padding: 28px;
  border: 1px solid rgba(255,255,255,.7);
  border-radius: 16px;
  background: rgba(255,255,255,.97);
  box-shadow: 0 20px 60px rgba(15,23,42,.20);
  text-align: center;
}

.big-loader {
  width: 34px;
  height: 34px;
  margin: 0 auto 17px;
  border: 3px solid #e4e7ec;
  border-top-color: #635bff;
  border-radius: 50%;
  animation: spin .7s linear infinite;
}

.loading-title {
  color: #101828;
  font-size: 15px;
  font-weight: 700;
}

.loading-text {
  margin-top: 6px;
  color: #667085;
  font-size: 12px;
  line-height: 1.5;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* =========================================================
   TOAST
========================================================= */

.toast {
  position: fixed;
  right: 24px;
  bottom: 24px;
  z-index: 10000;
  max-width: min(420px,calc(100% - 48px));
  padding: 12px 15px;
  border: 1px solid #d0d5dd;
  border-radius: 10px;
  background: #fff;
  color: #344054;
  box-shadow: 0 8px 30px rgba(16,24,40,.14);
  font-size: 13px;
  opacity: 0;
  pointer-events: none;
  transform: translateY(10px);
  transition: opacity .2s,transform .2s;
}

.toast.visible {
  opacity: 1;
  transform: translateY(0);
}

.toast.success { border-color: #abefc6; }

.toast.error {
  border-color: #fecdca;
  color: #b42318;
}

/* =========================================================
   MOBILE
========================================================= */

@media (max-width:760px) {
  .app {
    width: min(100% - 24px,1180px);
    padding-top: 28px;
  }

  .page-header h1 { font-size: 26px; }

  .toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .search { min-width: 0; }

  .summary { justify-content: space-between; }

  .card-header { display: none; }

  .category {
    grid-template-columns: minmax(0,1fr) 58px 58px;
    gap: 5px;
    padding: 14px 12px;
  }

  .category-info { padding-left: var(--indent) !important; }

  .category-name { white-space: normal; }

  .category-description { white-space: normal; }

  .category-meta { display: none; }

  .footer {
    bottom: 8px;
    align-items: stretch;
    flex-direction: column;
    gap: 9px;
  }

  .footer-status { justify-content: space-between; }

  .footer-actions { width: 100%; }

  .drop-button,.save-button {
    flex: 1;
  }

  .save-button { width: auto; }

  .change-star { right: calc(100% + 2px); }

  .toast {
    right: 12px;
    bottom: 12px;
    max-width: calc(100% - 24px);
  }
}

/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion:reduce) {
  *,*::before,*::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}
